INSERT INTO launch_scenario_seed VALUES ($curriculum$[{"slug": "incident_severity_triage", "title": "Incident severity triage", "brief": "Classify a live incident by impact, preserve evidence, start applicable clocks, and escalate proportionately.", "track": "launch-curriculum", "frameworks": ["iso27001", "nis2", "dora"], "difficulty": "practitioner", "entry_stage_id": "impact_assessment", "persona": {"role": "Incident Commander", "stance": "professionally challenging"}, "stages": [{"id": "impact_assessment", "sequence": 1, "agent_message": "Customer authentication is failing in two regions, but alert volume is modest. Operations asks whether this is only a low-severity technical event.", "demands": ["Classify the initial severity from known impact", "Explain the evidence and escalation basis for the decision"], "terminal": false, "choices": [{"id": "impact_assessment_correct", "label": "Declare a provisional high-severity incident, record impact and assumptions, and appoint an incident lead", "consequence": "The decision remains evidenced, bounded, and owned.", "is_correct": true, "rationale": "This is the supported response: it preserves accountable evidence and applies a.5.24, a.5.25 proportionately.", "next_stage": "clock_and_evidence", "risk_outcome": "controlled", "dimension_weights": {"control_mapping": 12, "evidence": 12, "escalation": 10, "remediation": 10}, "control_refs": ["a.5.24", "a.5.25"], "display_order": 1}, {"id": "impact_assessment_qualified", "label": "Open a medium-severity incident while explicitly setting a 15-minute impact reassessment trigger", "consequence": "Immediate exposure is limited, but a time-bound condition remains open.", "is_correct": false, "rationale": "This is a qualified alternative, not the reference answer: it limits immediate exposure but leaves a named evidence or governance condition unresolved under a.5.24, a.5.25.", "next_stage": "clock_and_evidence", "risk_outcome": "qualified_alternative", "dimension_weights": {"control_mapping": 6, "evidence": 5, "escalation": 6, "remediation": -2}, "control_refs": ["a.5.24", "a.5.25"], "display_order": 2}, {"id": "impact_assessment_failure", "label": "Classify it low because only a few alerts fired", "consequence": "The control conclusion is unsupported and risk increases.", "is_correct": false, "rationale": "This fails the control objective because it substitutes an unsupported conclusion for evidence required by a.5.24, a.5.25.", "next_stage": "clock_and_evidence", "risk_outcome": "control_failure", "dimension_weights": {"control_mapping": -12, "evidence": -10, "escalation": -12, "remediation": -10}, "control_refs": ["a.5.24", "a.5.25"], "display_order": 3}, {"id": "impact_assessment_defer", "label": "Wait for a complete root cause before opening an incident", "consequence": "The decision clock continues without accountable action.", "is_correct": false, "rationale": "Deferral leaves the risk unmanaged and misses the required escalation or remediation under a.5.24, a.5.25.", "next_stage": "clock_and_evidence", "risk_outcome": "unmanaged_delay", "dimension_weights": {"control_mapping": -8, "evidence": -8, "escalation": -15, "remediation": -8}, "control_refs": ["a.5.24", "a.5.25"], "display_order": 4}]}, {"id": "clock_and_evidence", "sequence": 2, "agent_message": "The team can restore service quickly, but the exact detection and business-awareness times differ across logs and chat.", "demands": ["Protect the timeline and applicable reporting clocks", "Explain the evidence and escalation basis for the decision"], "terminal": false, "choices": [{"id": "clock_and_evidence_correct", "label": "Record both timestamps with sources, preserve logs, and ask legal to determine which clock applies", "consequence": "The decision remains evidenced, bounded, and owned.", "is_correct": true, "rationale": "This is the supported response: it preserves accountable evidence and applies a.5.25, a.5.28 proportionately.", "next_stage": "severity_reassessment", "risk_outcome": "controlled", "dimension_weights": {"control_mapping": 12, "evidence": 12, "escalation": 10, "remediation": 10}, "control_refs": ["a.5.25", "a.5.28"], "display_order": 1}, {"id": "clock_and_evidence_qualified", "label": "Record the earliest supportable timestamp and flag the unresolved awareness time for immediate review", "consequence": "Immediate exposure is limited, but a time-bound condition remains open.", "is_correct": false, "rationale": "This is a qualified alternative, not the reference answer: it limits immediate exposure but leaves a named evidence or governance condition unresolved under a.5.25, a.5.28.", "next_stage": "severity_reassessment", "risk_outcome": "qualified_alternative", "dimension_weights": {"control_mapping": 6, "evidence": 5, "escalation": 6, "remediation": -2}, "control_refs": ["a.5.25", "a.5.28"], "display_order": 2}, {"id": "clock_and_evidence_failure", "label": "Use the later timestamp to maximize the reporting window", "consequence": "The control conclusion is unsupported and risk increases.", "is_correct": false, "rationale": "This fails the control objective because it substitutes an unsupported conclusion for evidence required by a.5.25, a.5.28.", "next_stage": "severity_reassessment", "risk_outcome": "control_failure", "dimension_weights": {"control_mapping": -12, "evidence": -10, "escalation": -12, "remediation": -10}, "control_refs": ["a.5.25", "a.5.28"], "display_order": 3}, {"id": "clock_and_evidence_defer", "label": "Restore first and reconstruct timestamps from memory tomorrow", "consequence": "The decision clock continues without accountable action.", "is_correct": false, "rationale": "Deferral leaves the risk unmanaged and misses the required escalation or remediation under a.5.25, a.5.28.", "next_stage": "severity_reassessment", "risk_outcome": "unmanaged_delay", "dimension_weights": {"control_mapping": -8, "evidence": -8, "escalation": -15, "remediation": -8}, "control_refs": ["a.5.25", "a.5.28"], "display_order": 4}]}, {"id": "severity_reassessment", "sequence": 3, "agent_message": "Service is restored, but 18,000 customers were unable to authenticate and regulated transactions were delayed.", "demands": ["Reassess severity and escalation after containment", "Explain the evidence and escalation basis for the decision"], "terminal": false, "choices": [{"id": "severity_reassessment_correct", "label": "Keep the incident major, escalate regulatory assessment, and document why restoration does not erase impact", "consequence": "The decision remains evidenced, bounded, and owned.", "is_correct": true, "rationale": "This is the supported response: it preserves accountable evidence and applies a.5.26, a.5.27 proportionately.", "next_stage": "complete", "risk_outcome": "controlled", "dimension_weights": {"control_mapping": 12, "evidence": 12, "escalation": 10, "remediation": 10}, "control_refs": ["a.5.26", "a.5.27"], "display_order": 1}, {"id": "severity_reassessment_qualified", "label": "Downgrade only operational urgency while retaining major-incident reporting and evidence duties", "consequence": "Immediate exposure is limited, but a time-bound condition remains open.", "is_correct": false, "rationale": "This is a qualified alternative, not the reference answer: it limits immediate exposure but leaves a named evidence or governance condition unresolved under a.5.26, a.5.27.", "next_stage": "complete", "risk_outcome": "qualified_alternative", "dimension_weights": {"control_mapping": 6, "evidence": 5, "escalation": 6, "remediation": -2}, "control_refs": ["a.5.26", "a.5.27"], "display_order": 2}, {"id": "severity_reassessment_failure", "label": "Close as minor because service is now restored", "consequence": "The control conclusion is unsupported and risk increases.", "is_correct": false, "rationale": "This fails the control objective because it substitutes an unsupported conclusion for evidence required by a.5.26, a.5.27.", "next_stage": "complete", "risk_outcome": "control_failure", "dimension_weights": {"control_mapping": -12, "evidence": -10, "escalation": -12, "remediation": -10}, "control_refs": ["a.5.26", "a.5.27"], "display_order": 3}, {"id": "severity_reassessment_defer", "label": "Leave severity unchanged without documenting the new facts", "consequence": "The decision clock continues without accountable action.", "is_correct": false, "rationale": "Deferral leaves the risk unmanaged and misses the required escalation or remediation under a.5.26, a.5.27.", "next_stage": "complete", "risk_outcome": "unmanaged_delay", "dimension_weights": {"control_mapping": -8, "evidence": -8, "escalation": -15, "remediation": -8}, "control_refs": ["a.5.26", "a.5.27"], "display_order": 4}]}, {"id": "complete", "sequence": 4, "agent_message": "", "demands": [], "terminal": true, "choices": []}], "content_hash": "81072d387bf6f9992c7a3936d5860c9687b84add711899239e76e000e97aec41"}, {"slug": "nonconformity_corrective_action", "title": "Nonconformity root cause and corrective action", "brief": "Separate correction from corrective action and build an evidenced response that prevents recurrence.", "track": "launch-curriculum", "frameworks": ["iso27001", "iso42001"], "difficulty": "practitioner", "entry_stage_id": "containment", "persona": {"role": "Process Owner", "stance": "professionally challenging"}, "stages": [{"id": "containment", "sequence": 1, "agent_message": "An auditor found six leavers with active accounts. Identity has now disabled those six accounts and asks to close the finding.", "demands": ["Separate immediate correction from corrective action", "Explain the evidence and escalation basis for the decision"], "terminal": false, "choices": [{"id": "containment_correct", "label": "Record the disablement as correction, preserve the sample, and open root-cause work", "consequence": "The decision remains evidenced, bounded, and owned.", "is_correct": true, "rationale": "This is the supported response: it preserves accountable evidence and applies clause.10.2, a.5.18 proportionately.", "next_stage": "root_cause", "risk_outcome": "controlled", "dimension_weights": {"control_mapping": 12, "evidence": 12, "escalation": 10, "remediation": 10}, "control_refs": ["clause.10.2", "a.5.18"], "display_order": 1}, {"id": "containment_qualified", "label": "Accept the correction temporarily but keep the nonconformity open with a dated root-cause owner", "consequence": "Immediate exposure is limited, but a time-bound condition remains open.", "is_correct": false, "rationale": "This is a qualified alternative, not the reference answer: it limits immediate exposure but leaves a named evidence or governance condition unresolved under clause.10.2, a.5.18.", "next_stage": "root_cause", "risk_outcome": "qualified_alternative", "dimension_weights": {"control_mapping": 6, "evidence": 5, "escalation": 6, "remediation": -2}, "control_refs": ["clause.10.2", "a.5.18"], "display_order": 2}, {"id": "containment_failure", "label": "Close because the sampled accounts are disabled", "consequence": "The control conclusion is unsupported and risk increases.", "is_correct": false, "rationale": "This fails the control objective because it substitutes an unsupported conclusion for evidence required by clause.10.2, a.5.18.", "next_stage": "root_cause", "risk_outcome": "control_failure", "dimension_weights": {"control_mapping": -12, "evidence": -10, "escalation": -12, "remediation": -10}, "control_refs": ["clause.10.2", "a.5.18"], "display_order": 3}, {"id": "containment_defer", "label": "Delete the sample after remediation to avoid duplicate records", "consequence": "The decision clock continues without accountable action.", "is_correct": false, "rationale": "Deferral leaves the risk unmanaged and misses the required escalation or remediation under clause.10.2, a.5.18.", "next_stage": "root_cause", "risk_outcome": "unmanaged_delay", "dimension_weights": {"control_mapping": -8, "evidence": -8, "escalation": -15, "remediation": -8}, "control_refs": ["clause.10.2", "a.5.18"], "display_order": 4}]}, {"id": "root_cause", "sequence": 2, "agent_message": "The owner says the cause was human error, but three HR feeds use different termination fields and one is not monitored.", "demands": ["Identify a controllable root cause", "Explain the evidence and escalation basis for the decision"], "terminal": false, "choices": [{"id": "root_cause_correct", "label": "Trace the failure to inconsistent feed design and missing exception monitoring, supported by process evidence", "consequence": "The decision remains evidenced, bounded, and owned.", "is_correct": true, "rationale": "This is the supported response: it preserves accountable evidence and applies clause.10.2, a.5.18 proportionately.", "next_stage": "effectiveness", "risk_outcome": "controlled", "dimension_weights": {"control_mapping": 12, "evidence": 12, "escalation": 10, "remediation": 10}, "control_refs": ["clause.10.2", "a.5.18"], "display_order": 1}, {"id": "root_cause_qualified", "label": "Record training weakness as a contributing cause while continuing analysis of feed and monitoring design", "consequence": "Immediate exposure is limited, but a time-bound condition remains open.", "is_correct": false, "rationale": "This is a qualified alternative, not the reference answer: it limits immediate exposure but leaves a named evidence or governance condition unresolved under clause.10.2, a.5.18.", "next_stage": "effectiveness", "risk_outcome": "qualified_alternative", "dimension_weights": {"control_mapping": 6, "evidence": 5, "escalation": 6, "remediation": -2}, "control_refs": ["clause.10.2", "a.5.18"], "display_order": 2}, {"id": "root_cause_failure", "label": "Name the analyst who missed the tickets as the root cause", "consequence": "The control conclusion is unsupported and risk increases.", "is_correct": false, "rationale": "This fails the control objective because it substitutes an unsupported conclusion for evidence required by clause.10.2, a.5.18.", "nex